  values(v_release_id, 9, 'g9_st3', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Tổng hợp vai trò của biến dị, di truyền và chọn lọc trong tiến hoá.', '{"textWithBlanks":"Chọn lọc tự nhiên làm một số đặc điểm di truyền trở nên phổ biến hơn qua nhiều [blank].","bankWords":["thế hệ","phút","trang sách"],"hint":"Dựa vào kiến thức của ải 10."}'::jsonb, '{"value":"thế hệ","explanation":"Từ đúng là “thế hệ”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 9 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 49–51. Tiến hoá và sự phát triển sự sống"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
